const fs = require("fs")
const dir = process.argv[2]
const text = fs.readFileSync(dir + "/summary.md", "utf8")
const anchors = {
  F1: {file: "bokehjs/src/lib/models/widgets/date_picker.ts", line_start: 78, line_end: 88},
  F2: {file: "bokehjs/src/lib/models/widgets/date_picker.ts", line_start: 79, line_end: 87},
  F3: {file: "tests/integration/widgets/test_datepicker.py", line_start: 52, line_end: 70},
  F4: {file: "tests/integration/widgets/test_datepicker.py", line_start: 43, line_end: 78},
  Q2: {file: "tests/integration/widgets/test_datepicker.py", line_start: 65, line_end: 65},
}
const findings = [], questions = []
const re = /^### ((F|Q)\d+)\. .*$/gm
let m
while ((m = re.exec(text)) != null) {
  const title = m[0].slice(4)
  const rest = text.slice(m.index + m[0].length)
  const end = rest.search(/^##+ /m)
  const quote = (end < 0 ? rest : rest.slice(0, end)).trim()
  if (quote.includes("\n")) throw new Error("multi-paragraph body for " + m[1])
  const row = {report_path: "summary.md", title, quote, ...(anchors[m[1]] || {})}
  ;(m[2] == "F" ? findings : questions).push(row)
}
for (const r of [...findings, ...questions]) {
  if (!text.includes(r.quote) || !text.includes("### " + r.title + "\n")) throw new Error("not verbatim")
}
fs.writeFileSync(dir + "/finding-index.json", JSON.stringify({findings, questions}, null, 2) + "\n")
console.log(findings.length, "findings,", questions.length, "questions")
for (const r of [...findings, ...questions]) console.log(r.title.slice(0, 60), "|", r.quote.length, "chars |", r.file || "-", r.line_start || "", r.line_end || "")
EOF
